"""
    :return: The number of integers within the range [a..b]
             that are divisible by k.

    >>> solution(6, 11, 2)
    3
    >>> solution(3, 14, 7)
    2
    """
def solution(a: int, b: int, k: int) -> int {
    count = ((b - a) + 1) // k;
    if ((b % k) == 0) {
        count += 1;
    }
    return count;
}

"""Convert from a single ARGB value to a tuple containing RGBA.

  Args:
    argb: Signed 32 bit integer containing an ARGB value.

  Returns:
    RGBA tuple.
  """
def _ArgbToRgbaTuple(argb: Any) -> object {
    unsigned_argb = argb % 4294967296;
    return (
        ((unsigned_argb >> 16) & 255),
        ((unsigned_argb >> 8) & 255),
        (unsigned_argb & 255),
        ((unsigned_argb >> 24) & 255)
    );
}

"""
    this function use to caculate f1 score
    :param precision:
    :param recall:
    :return:
    """
def f1_score_prob(precision: Any, recall: Any) -> object {
    f1_scores = [];
    for (x, y) in zip(precision, recall) {
        f1 = (2.0 * (x * y)) / (x + y);
        f1_scores.append(f1);
    }
    return f1_scores;
}

"""
    Construct version tag: "major.minor.micro" (or if 'dev' is specified: "major.minor.micro-dev").
    """
def construct_version_string(
    major: Any, minor: Any, micro: Any, dev: Any = None
) -> object {
    version_tag = f"{major}.{minor}.{micro}";
    if (dev is not None) {
        version_tag += f"-{dev}";
    }
    return version_tag;
}

"""Parse a I[.F] seconds value into (seconds, microseconds)."""
def _parsems(value: Any) -> object {
    if ("." not in value) {
        return (int(value), 0);
    } else {
        (i, f) = value.split(".");
        return (int(i), int(f.ljust(6, "0")[:6]));
    }
}

